import{_ as o,o as t,c as r,ag as e}from"./chunks/framework.CukOUUOK.js";const u=JSON.parse('{"title":"从琴弓到电塔：技术进步的红利到底归谁（上）","description":"技术进步让社会整体变富了，但红利不是均匀分配的。谁站在不可替代的节点上，谁就被动截获红利；谁站在可以被绕过的节点上，谁就只能看着红利从指缝间流走。从两百年前的音乐家到今天的房东，从苏联的土地实验到AI时代的白领危机，这个…","frontmatter":{"title":"从琴弓到电塔：技术进步的红利到底归谁（上）","categories":"权力与制度","tags":["劳动与经济","制度","权力","方法论"],"description":"技术进步让社会整体变富了，但红利不是均匀分配的。谁站在不可替代的节点上，谁就被动截获红利；谁站在可以被绕过的节点上，谁就只能看着红利从指缝间流走。从两百年前的音乐家到今天的房东，从苏联的土地实验到AI时代的白领危机，这个…","date":"2026-09-12T12:00:00.000Z","series":"从琴弓到电塔","seriesOrder":1},"headers":[],"relativePath":"posts/2026-09-12-from-bow-to-pylon-part-1.md","filePath":"posts/2026-09-12-from-bow-to-pylon-part-1.md","lastUpdated":1789992750000}'),p={name:"posts/2026-09-12-from-bow-to-pylon-part-1.md"};function n(s,a,l,h,i,c){return t(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="从琴弓到电塔-技术进步的红利到底归谁-上" tabindex="-1">从琴弓到电塔：技术进步的红利到底归谁（上） <a class="header-anchor" href="#从琴弓到电塔-技术进步的红利到底归谁-上" aria-label="Permalink to &quot;从琴弓到电塔：技术进步的红利到底归谁（上）&quot;">​</a></h1><blockquote><p><strong>技术进步让社会整体变富了，但红利不是均匀分配的。谁站在不可替代的节点上，谁就被动截获红利；谁站在可以被绕过的节点上，谁就只能看着红利从指缝间流走。从两百年前的音乐家到今天的房东，从苏联的土地实验到AI时代的白领危机，这个故事一直在重复。而最残酷的真相是：那些截获红利的人，往往不是凭能力站上去的，而是仅仅因为”恰好在那里”。</strong></p></blockquote><h3 id="引言-一支拉了两百年的琴弓" tabindex="-1">引言：一支拉了两百年的琴弓 <a class="header-anchor" href="#引言-一支拉了两百年的琴弓" aria-label="Permalink to &quot;引言：一支拉了两百年的琴弓&quot;">​</a></h3><p>1966年，经济学家威廉·鲍莫尔提出了一个著名的假说：演奏一首莫扎特的弦乐四重奏，在18世纪末需要4名乐手演奏20分钟；到了2026年，依然需要4名乐手老老实实拉满20分钟。两百多年过去，四重奏的物理生产效率毫无提升。但因为汽车、钢铁和计算机行业的效率翻了千万倍，全社会蛋糕急剧膨胀，音乐家的出场费也被迫水涨船高——这就是经济学中经典的”鲍莫尔成本病”。</p><p>鲍莫尔的本意，是用这个例子说明一个朴素的经济学原理：<strong>有些行业天然无法提升效率，但它们的成本会随着社会整体富裕程度的提高而不断上涨。</strong> 音乐家不是因为自己变得更厉害了才涨价，而是因为他们身后的世界变大了，而他们又恰好站在一个无法被绕过的节点上。</p><p>这个例子精妙、简洁、易于理解。但鲍莫尔本人可能没有意识到，他无意间打开的盒子远比他想象的大。</p><p>音乐家涨价，是因为他们站在一个无法被绕过的节点上——一首四重奏必须有人拉，机器替代不了。但仔细想想，还有没有什么东西，也是”站在那里不动”，却随着社会的进步不断升值？</p><p>比如一块地。</p><p>一块地不演奏音乐，不生产任何产品，它只是”在那里”。但当一家创造巨大价值的企业搬到它旁边时，它的价格会暴涨。而且涨幅远不止”与全社会工资同步”这么简单——它可以翻十倍、一百倍，而它本身没有做任何事情。</p><p>音乐家和土地，看似是两个完全不同的东西——一个是人，一个是物。但它们捕获红利的机制惊人地相似：<strong>都是因为”恰好在那里”，而恰好不可复制。</strong> 音乐家不可替代，是因为一首曲子必须有人现场演奏；土地不可替代，是因为你造不出第二块曼哈顿。两者都不是凭自己的”努力”或”能力”在涨价，而是凭”稀缺性”在被动地截获社会进步的红利。</p><p>鲍莫尔成本病揭示的是前者——人力服务因不可替代而被动涨价；经济学中另一个经典概念”级差地租”揭示的是后者——土地因位置稀缺而被动升值。两者看似分属不同领域，但指向同一个底层逻辑：</p><p><strong>技术进步的红利，从来不是均匀分配的。谁站在不可替代的节点上，谁就能被动地分享时代的红利；谁站在可以被绕过的节点上，谁就只能眼睁睁看着红利从指缝间流走。</strong></p><p>而更关键的问题是——那些”站在节点上”的人，到底是凭自己的劳动和能力站上去的，还是仅仅因为”恰好在那里”？</p><p>两百多年前，这个问题体现在音乐家身上。今天，它体现在土地、算力，以及每一个试图在技术浪潮中保住自身价值的劳动者身上。</p><p>而在回答这个问题之前，不妨先剧透一组来自2026年的数据：大模型巨头Anthropic发布的一份宏观经济报告推演，如果AI全面爆发，到2030年，白领知识工作者的实际工资将下跌11.5%，而电工、水暖工等蓝领工人的身价反而会暴涨33.6%。</p><p>为什么？这事得从两百年前的一支琴弓说起。</p><h3 id="第一章-蹭别人发展的人——土地食利的隐秘逻辑" tabindex="-1">第一章：蹭别人发展的人——土地食利的隐秘逻辑 <a class="header-anchor" href="#第一章-蹭别人发展的人——土地食利的隐秘逻辑" aria-label="Permalink to &quot;第一章：蹭别人发展的人——土地食利的隐秘逻辑&quot;">​</a></h3><h3 id="一、一个直觉性的愤怒" tabindex="-1">一、一个直觉性的愤怒 <a class="header-anchor" href="#一、一个直觉性的愤怒" aria-label="Permalink to &quot;一、一个直觉性的愤怒&quot;">​</a></h3><p>如果你在一线城市生活过，你大概率有过这样的体验：某家互联网大厂搬到你家附近，你的房租应声上涨。腾讯搬到深圳宝安大铲湾”企鹅岛”后，周边一房一厅从2400涨到3000，城中村单间从1300涨到1800。房东的逻辑直白得令人窒息：”腾讯一个小年轻来看房，开口就说2000行不行，我能不涨吗？”</p><p>杭州有句话叫”阿里定律”——阿里搬到哪，房价涨到哪。2020年蚂蚁集团总部选址杭州之江的消息一传出，某小区房源挂牌价直接从68万翻到186万。阿里云谷园区启用前半年，周边租金涨幅就超过20%。华为练秋湖研发中心2024年投用后，周边动迁安置房两房月租金从3000元直接翻倍到6000元。</p><p>更荒诞的细节是：2021年腾讯应届生房补从2000涨到4000，周边房东当晚就通知下季度租金上涨15%。你给员工加的福利，转了一圈全进了房东口袋。</p><p>这种愤怒是直觉性的：凭什么？腾讯的员工创造了价值，阿里的工程师写了代码，华为的研发人员搞出了技术——但最后赚得最多的，是那些什么都没干、只是”在那里”的房东。</p><h3 id="二、经济学给了这种愤怒一个精确的名字" tabindex="-1">二、经济学给了这种愤怒一个精确的名字 <a class="header-anchor" href="#二、经济学给了这种愤怒一个精确的名字" aria-label="Permalink to &quot;二、经济学给了这种愤怒一个精确的名字&quot;">​</a></h3><p>这种”什么都没干却赚得最多”的现象，在经济学中有一个精确的名字——<strong>级差地租</strong>。最早由大卫·李嘉图在19世纪系统阐述，后来马克思做了更深层的批判和发展。</p><p>核心逻辑是这样的：一块土地本身不创造任何价值。但当一家创造巨大价值的企业搬到它旁边时，这块土地因为”位置”的稀缺性而获得了超额收益。这个超额收益不是土地所有者创造的，而是企业的员工、周边的基础设施、整个社会的经济活动共同创造的——但它被土地所有者凭借”所有权”这一个字，完整地截获了。</p><p>马克思在研究”建筑地段地租”时，几乎就是这种现象的学术版描述：</p><blockquote><p>“土地所有者有明显的’被动性’，他的被动性表现在坐享其成上，比如，邻近修建了道路或地铁，他就会提高地租。”</p></blockquote><p>马克思150年前写的这段话，和”腾讯搬到哪，哪的房租就涨”，本质上是一回事。</p><h3 id="三、不只是音乐家和房东" tabindex="-1">三、不只是音乐家和房东 <a class="header-anchor" href="#三、不只是音乐家和房东" aria-label="Permalink to &quot;三、不只是音乐家和房东&quot;">​</a></h3><p>鲍莫尔成本病和级差地租，看似是两个不同的经济学概念，但它们指向同一个底层逻辑：<strong>社会越进步，”物”越便宜，”人”越贵——而”贵”的那部分，被稀缺资源的持有者截获了。</strong></p><p>这个逻辑适用于所有”人对人”的服务行业：医生、老师、理发师、保姆、律师。这就是为什么我们感觉看病、上学、请人服务越来越贵，而电视、手机、衣服却越来越便宜。制造业的生产率可以被机器成倍提升，但理发师一小时只能给一个人理发，这个效率两百年没变过。为了留住理发师，社会只能被动地给他涨工资，与全社会工资水平同步。结果就是：效率没变，成本不断上升。</p><p>而土地比理发师更极端——它连”效率”这个概念都不适用。一块地就是一块地，它不生产任何东西，它只是”在那里”。但正因为它的不可复制性，它成了整个经济体中最强大的”被动升值器”。</p><p>到这里，我们已经把现象描述清楚了：社会进步的红利被稀缺资源的持有者截获了。但接下来的问题是——<strong>这种截获是偶然的、可以被纠正的吗？还是说，它根植于某种更深层的制度逻辑？</strong> 要回答这个问题，我们需要请出一位对这种现象研究最深、批判最力的思想家。</p><h3 id="第二章-马克思没有放过地主——一个被误读的理论家" tabindex="-1">第二章：马克思没有放过地主——一个被误读的理论家 <a class="header-anchor" href="#第二章-马克思没有放过地主——一个被误读的理论家" aria-label="Permalink to &quot;第二章：马克思没有放过地主——一个被误读的理论家&quot;">​</a></h3><h3 id="一、《资本论》第三卷的整篇地租理论" tabindex="-1">一、《资本论》第三卷的整篇地租理论 <a class="header-anchor" href="#一、《资本论》第三卷的整篇地租理论" aria-label="Permalink to &quot;一、《资本论》第三卷的整篇地租理论&quot;">​</a></h3><p>很多人以为马克思只批判资本家、不批判地主，这是一个巨大的误解。事实上，马克思在《资本论》第三卷中用了整整一个篇章——<strong>第六篇，”超额利润转化为地租”</strong>——专门来解剖地主阶级。</p><p>他对地主的定性极其严厉。地租的本质是”剩余价值的无偿占有”——地主凭什么收租？不凭什么，凭的是”土地所有权垄断”这四个字。土地不是劳动产品，没有价值，地租纯粹是所有权在经济上的实现形式。马克思甚至指出，地主是农业进步的障碍——地主通过提高地租截取农场主追加投资的成果，导致没人愿意长期投入改良，”构成资本主义农业资本积累的制度性障碍”。</p><h3 id="二、为什么把地主放在资本家之后" tabindex="-1">二、为什么把地主放在资本家之后？ <a class="header-anchor" href="#二、为什么把地主放在资本家之后" aria-label="Permalink to &quot;二、为什么把地主放在资本家之后？&quot;">​</a></h3><p>既然马克思对地主批判得如此严厉，那他为什么把地主放在资本家之后来讨论？</p><p>答案不在于”地主不重要”，而在于<strong>在马克思观察的那个社会里，地主已经被资本逻辑吸收和改造了，不再是独立的对抗力量。</strong></p><p>在马克思生活的19世纪中后期，英国——他主要观察的对象——已经完成了从封建地主制向资本主义的转型。圈地运动从15世纪末一直持续到19世纪上半叶，到马克思写《资本论》的时候，英国传统的封建地主阶级已经基本完成了向资本主义的转化。他们已经不再是中世纪那种穿着长袍、坐在庄园里收实物地租的封建领主了，而是变成了资本主义化的土地食利者——把土地租给农业资本家，农业资本家雇佣工人生产，地主坐收地租。</p><p>地主和资本家形成了一条利益链条：资本家剥削工人创造剩余价值，地主凭借所有权从资本家手里切走一块。马克思在《资本论》第三卷中明确写道：</p><blockquote><p>“随着资本主义的发展，地主逐渐蜕变为食利者，土地所有权被资本主义化，<strong>地主与资本家在剥削雇佣劳动这一根本属性上趋于一致</strong>。”</p></blockquote><p>这就是为什么马克思把地主放在资本家之后来讨论——不是因为他觉得地主不重要，而是因为在他观察的那个社会里，地主已经被资本逻辑吸收和改造了，不再是独立的对抗力量，而是资本主义剥削体系的一个组成部分。你要推翻这个体系，核心矛盾在资本与劳动之间，地主只是这个矛盾的一个衍生环节。</p><p>恩格斯后来在评论亨利·乔治时更直接地说了这一点：</p><blockquote><p>“亨利·乔治宣布土地垄断是贫穷困苦的唯一原因……马克思学派的社会主义者也要求把土地交给社会，但<strong>不仅是土地，同样还有其他一切生产资料</strong>。亨利·乔治要求的是不触动现在的社会生产方式。”</p></blockquote><p>翻译成大白话：亨利·乔治觉得只要解决土地问题就万事大吉了，马克思说不对，土地问题是<strong>整个资本主义生产关系</strong>的一个症状，不是病因本身。你把地主打倒了但资本逻辑还在，新的食利形式还会冒出来。</p><h3 id="三、马克思的终极药方" tabindex="-1">三、马克思的终极药方 <a class="header-anchor" href="#三、马克思的终极药方" aria-label="Permalink to &quot;三、马克思的终极药方&quot;">​</a></h3><p>马克思开出的药方是明确的：<strong>废除土地私有制，土地归社会所有。</strong> 他在1872年的《论土地国有化》中写道：土地国有化将”彻底改变劳动与资本的关系”，”消灭工农业中的资本主义生产方式”。</p><p>他认为，一旦土地不再是私人财产，”涨价归公”就自然实现了——社会进步带来的土地增值不再被私人地主截获，而是归全体社会成员共享。</p><p>这个构想听起来简洁有力。但从1872年到今天，一百五十多年过去了，人类在落地这个构想的过程中，走出了一条远比理论复杂得多的路。</p><p><strong>【上篇完】</strong></p><p><em>下篇预告：苏联消灭了私人地主，却诞生了更强大的国家地主；中国在名义上实现了”土地全面公有”，实际运行中却催生了比私有制下更庞大的食利结构；美国用民主程序把”涨价归公”彻底废掉。食利结构为什么打不死？它背后的自我强化机制到底是什么？</em></p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2082127609798845220" target="_blank" rel="noreferrer">查看原文</a></p></blockquote>',55)])])}const b=o(p,[["render",n]]);export{u as __pageData,b as default};
